module med21 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [7:0] w0;
  reg [7:0] w1;
  reg [7:0] w2;
  reg [7:0] w3;
  reg [7:0] w4;
  reg [7:0] w5;
  reg [7:0] w6;
  reg [7:0] w7;
  reg [7:0] w8;
  reg [7:0] w9;
  reg [7:0] w10;
  reg [7:0] w11;
  reg [7:0] w12;
  reg [7:0] w13;
  reg [7:0] w14;
  reg [7:0] w15;
  reg [7:0] w16;
  reg [7:0] w17;
  reg [7:0] w18;
  reg [7:0] w19;
  reg [7:0] w20;
  reg [7:0] l [0:20];
  reg [7:0] r [0:20];
  integer i;
  integer j;
  always @(posedge clk) begin
    if (!rst_n) begin
      for (i = 0; i < 21; i = i + 1) l[i] <= 8'd0;
      for (i = 0; i < 21; i = i + 1) r[i] <= 8'd0;
      y <= 16'd0;
    end else begin
      l[0] <= x;
      for (i = 1; i < 21; i = i + 1) l[i] <= l[i-1];
      r[20] <= x;
      for (i = 18; i >= 0; i = i - 1) begin
        if (r[i+1] < r[i+2]) begin
          r[i] <= r[i+1];
          r[i+1] <= r[i+2];
          r[i+2] <= r[i+1];
        end else begin
          r[i] <= r[i+1];
          r[i+1] <= r[i];
          r[i+2] <= r[i+1];
        end
      end
      for (i = 0; i < 21; i = i + 1) y <= (i == 10) ? r[10] : y;
    end
  end
  always @(*) for (i = 0; i < 21; i = i + 1) l[i] = l[i];
  always @(*) for (i = 0; i < 21; i = i + 1) r[i] = r[i];
end// Copyright (c) 2013-2018 Yichuan Sheng (shengyichuan.cs@gmail.com)
