// file LICENSE_1_0.txt or copy at http://www.boost.org/LICENSE_1_0.txt)

module fifo_with_rst #(
    parameter WIDTH=32, DEPTH=8, ALMOST_FULL_THRESH= 1<<(DEPTH-1),
              ALMOST_EMPTY_THRESH= 1, INIT_VALUE = 0
)(
    input wire clk, rst_n,
    input wire write, read,
    input wire [WIDTH-1:0] data_in,
    output reg [WIDTH-1:0] data_out,
    output reg full, almost_full,
    output reg empty, almost_empty
);
    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [DEPTH-1:0] head, tail;
    integer i;

    always @(posedge clk) begin
        if (!rst_n) begin
            head <= 0;
            tail <= 0;
            full <= 0;
            almost_full <= 0;
            empty <= 1;
            almost_empty <= 0;
            for (i = 0; i < DEPTH; i = i + 1) mem[i] <= INIT_VALUE;
        end else begin
            if (write && !full) begin
                mem[head] <= data_in;
                head <= head + 1;
                if (head == DEPTH) head <= 0;
                if (head == tail+1) full <= 1;
                if (head == tail + ALMOST_FULL_THRESH) almost_full <= 1;
                empty <= 0;
                if (tail == head - 1) almost_empty <= 1;
            end
            if (read && !empty) begin
                data_out <= mem[tail];
                tail <= tail + 1;
                if (tail == DEPTH) tail <= 0;
                full <= 0;
                if (tail + 1 == head) empty <= 1;
                if (tail == DEPTH-ALMOST_EMPTY_THRESH) almost_empty <= 1;
                if (tail == head - ALMOST_FULL_THRESH) almost_full <= 0;
            end
        end
    end
endmodule

